const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function netFetch(req,tries){ let last; for(let i=0;i<(tries||3);i++){ try{ const r=await fetch(req,{cache:i?'reload':'default'}); if(r&&(r.ok||r.status===404)) return r; last=r; }catch(e){ last=e; } await sleep(400*Math.pow(2,i)); } if(last instanceof Response) return last; throw last||new Error('net'); }
