self.addEventListener('fetch',e=>{ const r=e.request; if(r.method!=='GET') return; let u; try{ u=new URL(r.url); }catch(_){ return; } if(u.origin!==location.origin) return;
  if(r.mode==='navigate'){ e.respondWith((async()=>{ let h=null; try{ h=await caches.open(HTML_CACHE); }catch(_){ }
      try{ const net=fetch(r); const res=await Promise.race([net,new Promise((_,rej)=>setTimeout(()=>rej('slow'),4000))]); if(res&&res.ok&&res.status===200&&h) put(h,'./',res.clone()); return res; }
      catch(_){ try{ const c=h&&await h.match('./'); if(c&&c.ok) return c; }catch(__){ } return fetch(r); } })()); return; }
  if(/\/a\/[0-9a-f]{16}\./.test(u.pathname)){ if(r.headers.get('range')) return; /* video range requests: browser default */
    e.respondWith((async()=>{ let a=null;
      try{ a=await caches.open(ASSET_CACHE); const retry=u.searchParams.has('r'); /* page retry after a broken image: never trust the cache */ const c=await a.match(r,{ignoreSearch:true}); if(!retry&&goodAsset(c)&&(await c.clone().blob()).size>0) return c; if(c) await a.delete(r,{ignoreSearch:true}).catch(()=>{}); }catch(_){ a=null; }
      const res=await netFetch(r,3); if(a&&goodAsset(res)) put(a,new Request(u.origin+u.pathname),res.clone()); return res; })().catch(()=>fetch(r))); }
});
